entries[127124] = { ["name"] = "Pulverfass des Schlossermeisters", ["text"] = "Wirken in 2 sek.\nTools: Gyromatischer Mikroregler\nReagenzien:\nEinfaches Holz , Hochexplosives Schwarzpulver\nBerufsausbilder:\nIngenieurskunst von Pandaria (1)\nKosten:\n10\n\nBenutzen: Sprengt verschlossene Türen und Kisten auf, die eine Fertigkeit von bis zu 35 im Schlossknacken benötigen.\nBenötigt Ingenieurskunst von Pandaria\n(1)" }
entries[127127] = { ["name"] = "G91-Landhai", ["text"] = "Wirken in 2 sek.\nTools: Gyromatischer Mikroregler\nReagenzien:\nGeistereisenbolzen (2), Hochexplosives Schwarzpulver (2)\nBerufsausbilder:\nIngenieurskunst von Pandaria (1)\nKosten:\n10\n\n(3)\nBenutzen: Fügt einem Gegner in bis zu 45 Metern Entfernung und Gegnern innerhalb von 10 Metern um das Primärziel 688 Feuerschaden zu. (1 Min Abklingzeit)\n32" }
entries[127128] = { ["name"] = "Goblindrachengewehr - Nr. II", ["text"] = "Wirken in 3 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nGeistereisenbolzen (3), Hochexplosives Schwarzpulver (8)\nBerufsausbilder:\nIngenieurskunst von Pandaria (25)\nKosten:\n1\n\nBenutzen: Entfesselt eine Blitzentladung, die Zielen in einem 10 Meter großen kegelförmigen Bereich vor dem Wirkenden 4 Sek. lang alle 0.5 Sek. 48 Naturschaden zufügt.\n\nKann während der Bewegung gewirkt werden. (30 Sek. Abklingzeit)\n50 Aufladungen\n32" }
entries[127129] = { ["name"] = "Blingtron 4000", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nLebendiger Stahl (4), Trilliumbarren (4), Geistereisenbarren (4), Aragonit (4), Dioptas (4), Geist der Harmonie (4)\nBerufsausbilder:\nIngenieurskunst von Pandaria (75)\nKosten:\n3\n50\n\nBlingtron 4000\nWird beim Aufheben gebunden\nSpielzeug\nBenutzen: Setzt den unglaublichen Blingtron 4000 zusammen, einen Roboter von unendlichem Reichtum. Bling, wie er gerne genannt wird, händigt jedem, der mit ihm spricht, ein zufälliges Geschenk aus, aber nur ein Mal pro Tag. Hält 10 Min. lang an. (4 Std. Abklingzeit)\nBenötigt Ingenieurskunst von Pandaria\n(75)" }
entries[127130] = { ["name"] = "Nebeldurchdringende Brille", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nGeistereisenbolzen (8), Geist der Harmonie (2)\nBerufsausbilder:\nIngenieurskunst von Pandaria (1)\nKosten:\n10\n\nNebeldurchdringende Brille\nWird beim Anlegen gebunden\nKopf\nAnlegen: Ermöglicht Euch, zusätzliche Erzadern und Kräutervorkommen aufzuspüren, während Ihr Euch in Pandaria befindet.\n\"Obwohl diese Brille sehr modisch ist, muss sie nicht aufgesetzt werden, um von ihrer Spezialfähigkeit zu profitieren.\"" }
entries[127131] = { ["name"] = "Thermischer Amboss", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nHochexplosives Schwarzpulver (8), Geistereisenbolzen (6)\nBerufsausbilder:\nIngenieurskunst von Pandaria (25)\nKosten:\n1\n\nBenutzen: Platziert einen thermischen Amboss zu Euren Füßen, der allen in der Nähe befindlichen Charakteren erlaubt, sowohl einen Amboss als auch eine Schmiede zu benutzen. Hält 5 Min. lang an. (5 Min Abklingzeit)\n20 Aufladungen" }
entries[127132] = { ["name"] = "Wurmlochgenerator: Pandaria", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nTrilliumbarren (12), Geist der Harmonie (2)\nBerufsausbilder:\nIngenieurskunst von Pandaria (45)\nKosten:\n1\n75\n\nWurmlochgenerator: Pandaria\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Teleportiert Euch an irgendeinen Ort in Pandaria. Der exakte Ort ist schwer zu bestimmen, aber er ist wahrscheinlich ziemlich weit entfernt. (15 Min Abklingzeit)\n29\nBenötigt Ingenieurskunst von Pandaria\n(1)\n\"An der Seite ist eine winzige Notiz: Huiiiiiiiiiiiiiii!\"" }
entries[127134] = { ["name"] = "Geistereisendrachling", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nWindwollstoff (12), Geistereisenbolzen (8), Hochexplosives Schwarzpulver (4)\nOptionale Reagenzien:\n[] (#49)\nBerufsausbilder:\nIngenieurskunst von Pandaria (25)\nKosten:\n1\n\nGeistereisendrachling\nWird beim Anlegen gebunden\nEinzigartig anlegbarSchmuck\nZahnradsockel\nZahnradsockel\nZahnradsockel\n\nAnlegen: Eure Angriffe haben eine Chance, einen Geistereisendrachling zu beschwören, der 20 Sek. lang an Eurer Seite kämpft. (Procchance: 25%, 1Min. Abklingzeit)\n33" }
entries[127135] = { ["name"] = "Mechanischer Pandarendrachling", ["text"] = "Wirken in 3.5 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nGeistereisenbarren (4), Trilliumbarren (6), Geist der Harmonie (2)\nBerufsausbilder:\nIngenieurskunst von Pandaria (50)\nKosten:\n2\n\nMechanischer Pandarendrachling\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Welpling beschwören oder wieder freigeben.\n1 - 80 ( 80)" }
entries[127136] = { ["name"] = "Großwildjäger", ["text"] = "Wirken in 3 sek.\nTools: Schmiedehammer , Gyromatischer Mikroregler\nReagenzien:\nGeistereisenbolzen (12), Haarfeiner Sprengstoffauslöser , Schäftung aus Walnussholz , Verspiegeltes Zielfernrohr\nOptionale Reagenzien:\n[] (#49)\nBerufsausbilder:\nIngenieurskunst von Pandaria (1)\nKosten:\n10\n\nGroßwildjäger\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n6 - 12 Schaden Geschwindigkeit 3.00\n(3.0 Schaden pro Sekunde)\n+3 Beweglichkeit\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 2.\n\nPrismatischer Sockel\nSockelbonus: + 1 Beweglichkeit\n\nHaltbarkeit 100 / 100\n32" }
entries[127137] = { ["name"] = "Trilliumlangstreckenpräzisionsgewehr", ["text"] = "Wirken in 3 sek.\nTools: Schmiedehammer , Gyromatischer Mikroregler\nReagenzien:\nTrilliumbarren (12), Haarfeiner Sprengstoffauslöser , Geist der Harmonie , Fürst von Schmetternichs Todeszielfernrohr\nBerufsausbilder:\nIngenieurskunst von Pandaria (40)\nKosten:\n1\n50\n\nTrilliumlangstreckenpräzisionsgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n6 - 12 Schaden Geschwindigkeit 3.00\n(3.0 Schaden pro Sekunde)\n+3 Beweglichkeit\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 4.\n\nPrismatischer Sockel\nSockelbonus: + 0 Beweglichkeit\n\nHaltbarkeit 100 / 100\n35" }
entries[127138] = { ["name"] = "Rakete mit abgereichertem Kyparium", ["text"] = "Wirken in 3.5 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nLebendiger Stahl (12), Kyparit (200), Kugel der Geheimnisse (3), Hochexplosives Schwarzpulver (12), Geist der Harmonie (12), Geistereisenbolzen (20)\nBerufsausbilder:\nIngenieurskunst von Pandaria (75)\nKosten:\n3\n50\n\nRakete mit abgereichertem Kyparium\nEinzigartig\nReittier (Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nEine Höhepunkt goblinischer Ingenieurskunst! Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n1 - 80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wenn Kyparit seine Bernsteinessenz entzogen wird, kommt es kaum noch zu Korrosion durch Raketentreibstoff.\"\nBeruf:\nIngenieurskunst" }
entries[127139] = { ["name"] = "Geosynchroner Weltendreher", ["text"] = "Wirken in 3.5 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nLebendiger Stahl (12), Trilliumbarren (12), Geist der Harmonie (12), Geistereisenbolzen (20), Kugel der Geheimnisse (3)\nBerufsausbilder:\nIngenieurskunst von Pandaria (75)\nKosten:\n3\n50\n\nGeosynchroner Weltendreher\nEinzigartig\nReittier (Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nEine Apparatur, die die Welt selbst unter Euch rotieren lässt! Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n1 - 80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Rakete wurde ursprünglich entworfen, um die Umdrehung der Welt zu beschleunigen und so die Nächte zu verkürzen. Wenn Gnome unter Schlafmangel leiden, setzen sie sich große Ziele.\"\nBeruf:\nIngenieurskunst" }
