entries[127154] = { ["name"] = "Onyxwolkenschlange", ["text"] = "Wirken in 1.5 sek.\nBeschwört eine reitbare Onyxwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n\"Onyxwolkenschlangen sind aggressiver und waghalsiger als ihre Verwandten, die himmlischen Onyxwolkenschlangen.\"\nQuest:\nÜberraschungsangriff!\nOrt:\nTonlongsteppe" }
entries[127156] = { ["name"] = "Purpurwolkenschlange", ["text"] = "Wirken in 1.5 sek.\nBeschwört eine reitbare Purpurwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n\"Purpurwolkenschlangen neigen zu Träumereien und begeben sich spontan auf scheinbar zufällige Reisen, die gelegentlich Tage andauern.\"\nErfolg:\nHeldenruhm von Pandaria\nKategorie:\nDungeons & Schlachtzüge" }
entries[127157] = { ["name"] = "Rüstung zerschmettern", ["text"] = "Nahkampfreichweite\nSofort\nZerquetscht einen Gegner und verringert seine Rüstung 8 Sek. lang um 10%. Stapelbar." }
entries[127158] = { ["name"] = "Himmlische Onyxwolkenschlange", ["text"] = "Wirken in 1.5 sek.\nBeschwört eine reitbare himmlische Onyxwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n\"Himmlische Onyxwolkenschlangen sind von Geburt an am ganzen Körper mit violetten Schuppen bedeckt. Mit der Zeit verdunkeln sich diese Schuppen zum Farbton von Onyx.\"\nBeute von:\nSha des Zorns\nOrt:\nKun-Lai-Gipfel" }
entries[127159] = { ["name"] = "Desorientieren", ["text"] = "20 Meter Reichweite\nSofort\nDas hätte Euch umbringen können, Mann!" }
entries[127160] = { ["name"] = "Aus Lache teleportieren" }
entries[127161] = { ["name"] = "Himmlische Purpurwolkenschlange", ["text"] = "Wirken in 1.5 sek.\nBeschwört eine reitbare himmlische Purpurwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n\"Himmlische Purpurwolkenschlangen zählen zu den edelsten Drachen.\"\nErfolg:\nRuhm des Pandaria-Schlachtzüglers\nKategorie:\nDungeons & Schlachtzüge" }
entries[127163] = { ["name"] = "Kugel der Macht", ["text"] = "Unbegrenzte Reichweite\nSofort\nIhr tragt die Kugel der Macht.\nDas Tragen der Kugel verschafft Eurem Team Siegpunkte.\nVerringert die erhaltene Heilung um 0%." }
entries[127164] = { ["name"] = "Himmlische Goldwolkenschlange", ["text"] = "Wirken in 1.5 sek.\nBeschwört eine reitbare himmlische Goldwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n\"Dieser großen Kreatur, die glüht wie ein Sonnenaufgang über den Bergen, entspringt Wärme und Hoffnung.\"\nVerkäufer:\nNebelwirker Ku\nZone:\nZeitlose Insel\nKaiser Shaohao - Ehrfürchtig" }
entries[127165] = { ["name"] = "Yu'lei, Tochter der Jade", ["text"] = "Wirken in 1.5 sek.\nBeschwört Yu'lei, Tochter der Jade, und gibt sie wieder frei. Das ist ein Flugreittier.\n\"Dieser großen Kreatur, die wie Mondlicht durch feinste Jade schimmert, entspringt Wärme und Weisheit.\"\nVerkäufer:\nNebelwirkerin Xia\nZone:\nZeitlose Insel\nKosten:\n5.000" }
entries[127169] = { ["name"] = "Himmlische Azurwolkenschlange", ["text"] = "Wirken in 1.5 sek.\nBeschwört eine reitbare himmlische Azurwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n\"Dieser großen Kreatur, die wie ein wolkenloser Himmel an einem Sommerabend leuchtet, entspringt Wärme und Gelassenheit.\"\nErfolg:\nHerr der Reittiere\nKategorie:\nReittiere" }
entries[127170] = { ["name"] = "Astrale Wolkenschlange", ["text"] = "Wirken in 1.5 sek.\nBeschwört eine reitbare astrale Wolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n\"Man geht davon aus, dass die astralen Wolkenschlangen Antworten auf einige der größten Geheimnisse des Lebens kennen. Zu dumm, dass sie nicht sprechen können.\"\nBeute von:\nBehälter aus reiner Energie" }
entries[127171] = { ["name"] = "Heimtückisches Zerfleischen", ["text"] = "Nahkampfreichweite\nSofort 5 sek. Abklingzeit\nGreift einen Gegner brutal an und fügt ihm 9 Sek. lang alle 1 Sek. körperlichen Schaden zu." }
