entries[127174] = { ["name"] = "Azurblauer Reitkranich", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren azurblauen Reitkranich und gibt ihn wieder frei.\n\"Der majestätische Kranich ist ein geschätzter Freund der Pandaren.\"\nVerkäufer:\nJaluu der Spendable\nZone:\nTal der Ewigen Blüten\nGoldener Lotus - Ehrfürchtig\nKosten:\n500" }
