entries[127178] = { ["name"] = "Dschungelreitkranich", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Dschungelreitkranich und gibt ihn wieder frei.\n\"Als geschätztes Reittier ist der Dschungelkranich im Süden Pandarias für seine Geschwindigkeit und Beweglichkeit bekannt, die das Leben auf der Flucht vor den Krasaritigern mit sich bringt.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
