entries[127209] = { ["name"] = "Schwarzes Reityak", ["text"] = "Wirken in 1.5 sek.\nBeschwört ein reitbares schwarzes Reityak oder gibt es wieder frei.\n\"Grummel, die nachts zum Kun-Lai-Gipfel reisen, bevorzugen diese dunkelhaarigen Yaks, damit sie nicht gesehen werden. Allerdings entfernen sie dazu erst einmal die Glocken aus deren Schmuck.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
