entries[127262] = { ["name"] = "Schmerzstecher", ["text"] = "Sofort\nGewährt dem Zaubernden die Chance, mit jedem Treffer bei seinen Opfern Schmerz auszulösen. Der Schmerz verringert 10 Sek. lang die Chance des Opfers zu blockieren, auszuweichen oder zu parieren um 5%.\n(Procchance: 30%)" }
