entries[127271] = { ["name"] = "Purpurroter Wasserschreiter", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren purpurroten Wasserschreiter oder gibt ihn wieder frei.\n\"Normalerweise sind Käfer als Köder da, doch wie könnte man diesem hier in die Augen sehen und so etwas auch nur denken?\" - Nat Pagle\nVerkäufer:\nNat Pagle\nZone:\nGarnison: Angelhütte\nNat Pagle - Wohlwollend\nKosten:\n100" }
