entries[127281] = { ["name"] = "Stibitzte Magie", ["text"] = "40 Meter Reichweite\nWirken in 3 sek. 5 sek. Abklingzeit\nÜberzieht einen Gegner mit gestohlener Magie und fügt Arkanschaden zu." }
