entries[127370] = { ["name"] = "Blutregen", ["text"] = "Sofort\nKlaxxiverstärkung\nVerliehen von Xaril dem Vergifteten Geist.\n\nGewährt Euren Angriffen eine Chance von 100%, Gegnern 'Istabiles Serum' zu injizieren.\n\nInstabiles Serum\nBei 5 Stapeln erleidet Euer Primärziel zusätzlichen Schaden und alle Gegner in der Nähe des Primärziels werden 5 Sek. lang betäubt.\n\nEs kann immer nur jeweils eine Klaxxiverstärkung aktiv sein. Funktioniert nur in der Schreckensöde.\n(1s Abklingzeit)" }
