entries[127375] = { ["name"] = "Tempokönig", ["text"] = "Sofort\nKlaxxikräftigung\nVerliehen von Ka'roz der Heuschrecke.\n\nLässt Euch einmal alle 5 Sek. ein zweites Mal springen.\n\nVerleiht Euch beim Töten eines Gegners, der Erfahrung gewährt, den Effekt 'Tempokönig', der 60 Sek. lang anhält.\n\nTempokönig\nErhöht die Bewegungsgeschwindigkeit um 10%. Bis zu 5-mal stapelbar.\n\nEs kann immer nur jeweils eine Klaxxikräftigung aktiv sein. Funktioniert nur in der Schreckensöde." }
